1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
bpf: Reject sleepable kprobe_multi programs at attach time

kprobe.multi programs run in atomic/RCU context and cannot sleep.
However, bpf_kprobe_multi_link_attach() did not validate whether the
program being attached had the sleepable flag set, allowing sleepable
helpers such as bpf_copy_from_user() to be invoked from a non-sleepable
context.

This causes a "sleeping function called from invalid context" splat:

  BUG: sleeping function called from invalid context at ./include/linux/uaccess.h:169
  in_atomic(): 1, irqs_disabled(): 0, non_block: 0, pid: 1787, name: sudo
  preempt_count: 1, expected: 0
  RCU nest depth: 2, expected: 0

Fix this by rejecting sleepable programs early in
bpf_kprobe_multi_link_attach(), before any further processing.

Fixes: 0dcac2725406 ("bpf: Add multi kprobe link")
Signed-off-by: Varun R Mallya <varunrmallya@gmail.com>
Acked-by: Kumar Kartikeya Dwivedi <memxor@gmail.com>
Acked-by: Leon Hwang <leon.hwang@linux.dev>
Acked-by: Jiri Olsa <jolsa@kernel.org>
Link: https://lore.kernel.org/r/20260401191126.440683-1-varunrmallya@gmail.com
Signed-off-by: Alexei Starovoitov <ast@kernel.org>

Here is the root cause:
The bug occurred because `bpf_kprobe_multi_link_attach()` did not validate whether the program being attached had the `sleepable` flag set. Since kprobe_multi programs run in atomic/RCU context where sleeping is not allowed, allowing a sleepable program to attach caused a "sleeping function called from invalid context" splat when sleepable helpers (e.g., `bpf_copy_from_user()`) were invoked.

Here is the patch:

 int bpf_kprobe_multi_link_attach(const union bpf_attr *attr, struct bpf_prog *prog)
 {
 	struct bpf_kprobe_multi_link *link = NULL;
 	struct bpf_link_primer link_primer;
 	void __user *ucookies;
 	unsigned long *addrs;
 	u32 flags, cnt, size;
 	void __user *uaddrs;
 	u64 *cookies = NULL;
 	void __user *usyms;
 	int err;

 	/* no support for 32bit archs yet */
 	if (sizeof(u64) != sizeof(void *))
 		return -EOPNOTSUPP;

 	if (attr->link_create.flags)
 		return -EINVAL;

 	if (!is_kprobe_multi(prog))
 		return -EINVAL;

+	/* kprobe_multi is not allowed to be sleepable. */
+	if (prog->sleepable)
+		return -EINVAL;
+
 	/* Writing to context is not allowed for kprobes. */
 	if (prog->aux->kprobe_write_ctx)
 		return -EINVAL;

 	flags = attr->link_create.kprobe_multi.flags;
 	if (flags & ~BPF_F_KPROBE_MULTI_RETURN)
 		return -EINVAL;

 	uaddrs = u64_to_user_ptr(attr->link_create.kprobe_multi.addrs);
 	usyms = u64_to_user_ptr(attr->link_create.kprobe_multi.syms);
 	if (!!uaddrs == !!usyms)
 		return -EINVAL;

 	cnt = attr->link_create.kprobe_multi.cnt;
 	if (!cnt)
 		return -EINVAL;
 	if (cnt > MAX_KPROBE_MULTI_CNT)
 		return -E2BIG;

 	size = cnt * sizeof(*addrs);
 	addrs = kvmalloc_array(cnt, sizeof(*addrs), GFP_KERNEL);
 	if (!addrs)
 		return -ENOMEM;

 	ucookies = u64_to_user_ptr(attr->link_create.kprobe_multi.cookies);
 	if (ucookies) {
 		cookies = kvmalloc_array(cnt, sizeof(*addrs), GFP_KERNEL);
 		if (!cookies) {
 			err = -ENOMEM;
 			goto error;
 		}
 		if (copy_from_user(cookies, ucookies, size)) {
 			err = -EFAULT;
 			goto error;
 		}
 	}

 	if (uaddrs) {
 		if (copy_from_user(addrs, uaddrs, size)) {
 			err = -EFAULT;
 			goto error;
 		}
 	} else {
 		struct multi_symbols_sort data = {
 			.cookies = cookies,
 		};
 		struct user_syms us;

 		err = copy_user_syms(&us, usyms, cnt);
 		if (err)
 			goto error;

 		if (cookies)
 			data.funcs = us.syms;

 		sort_r(us.syms, cnt, sizeof(*us.syms), symbols_cmp_r,
 		       symbols_swap_r, &data);

 		err = ftrace_lookup_symbols(us.syms, cnt, addrs);
 		free_user_syms(&us);
 		if (err)
 			goto error;
 	}

 	if (prog->kprobe_override && addrs_check_error_injection_list(addrs, cnt)) {
 		err = -EINVAL;
 		goto error;
 	}

 	link = kzalloc_obj(*link);
 	if (!link) {
 		err = -ENOMEM;
 		goto error;
 	}

 	bpf_link_init(&link->link, BPF_LINK_TYPE_KPROBE_MULTI,
 		      &bpf_kprobe_multi_link_lops, prog, attr->link_create.attach_type);

 	err = bpf_link_prime(&link->link, &link_primer);
 	if (err)
 		goto error;

 	if (!(flags & BPF_F_KPROBE_MULTI_RETURN))
 		link->fp.entry_handler = kprobe_multi_link_handler;
 	if ((flags & BPF_F_KPROBE_MULTI_RETURN) || is_kprobe_session(prog))
 		link->fp.exit_handler = kprobe_multi_link_exit_handler;
 	if (is_kprobe_session(prog))
 		link->fp.entry_data_size = sizeof(u64);

 	link->addrs = addrs;
 	link->cookies = cookies;
 	link->cnt = cnt;
 	link->link.flags = flags;

 	if (cookies) {
 		/*
 		 * Sorting addresses will trigger sorting cookies as well
 		 * (check bpf_kprobe_multi_cookie_swap). This way we can
 		 * find cookie based on the address in bpf_get_attach_cookie
 		 * helper.
 		 */
 		sort_r(addrs, cnt, sizeof(*addrs),
 		       bpf_kprobe_multi_cookie_cmp,
 		       bpf_kprobe_multi_cookie_swap,
 		       link);
 	}

 	err = get_modules_for_addrs(&link->mods, addrs, cnt);
 	if (err < 0) {
 		bpf_link_cleanup(&link_primer);
 		return err;
 	}
 	link->mods_cnt = err;

 	err = register_fprobe_ips(&link->fp, addrs, cnt);
 	if (err) {
 		kprobe_multi_put_modules(link->mods, link->mods_cnt);
 		bpf_link_cleanup(&link_primer);
 		return err;
 	}

 	return bpf_link_settle(&link_primer);

 error:
 	kfree(link);
 	kvfree(addrs);
 	kvfree(cookies);
 	return err;
 }
 #else /* !CONFIG_FPROBE */


